/** Shared job types, constants, validation, and API serialization. No I/O happens here. */

export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';

/** Processing constants shared by the server and worker. */
export const STEP_MS = 100;
export const RETRY_DELAY_MS = 500;
export const MAX_ATTEMPTS = 3;
export const TRANSIENT_ERROR = 'transient failure';
export const MAX_INPUT_LENGTH = 1000;
export const MAX_STEPS = 20;
export const MAX_FAIL_ATTEMPTS = 5;
export const DEFAULT_STEPS = 5;
export const DEFAULT_FAIL_ATTEMPTS = 0;

/** A row of the `jobs` table, exactly as SQLite returns it. */
export interface JobRow {
  seq: number;
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  fail_attempts: number;
  attempts: number;
  completed: number;
  output: string | null;
  error: string | null;
  created_at: string;
  updated_at: string;
  idempotency_key: string | null;
  available_at: number;
}

/** The public job representation returned by every endpoint. */
export interface ApiJob {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  progress: { completed: number; total: number };
  result: { output: string } | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

export interface NewJob {
  input: string;
  steps: number;
  failAttempts: number;
}

export interface FieldError {
  field: string;
  message: string;
}

export function toApiJob(row: JobRow): ApiJob {
  return {
    id: row.id,
    status: row.status,
    input: row.input,
    steps: row.steps,
    failAttempts: row.fail_attempts,
    attempts: row.attempts,
    progress: { completed: row.completed, total: row.steps },
    result: row.status === 'completed' && row.output !== null ? { output: row.output } : null,
    error: row.status === 'failed' ? row.error : null,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

const ALLOWED_FIELDS = new Set(['input', 'steps', 'failAttempts']);
const IDEMPOTENCY_KEY_PATTERN = /^[A-Za-z0-9_-]{1,128}$/;

function integerField(body: Record<string, unknown>, name: string, min: number, max: number, fallback: number, errors: FieldError[]): number {
  if (!Object.hasOwn(body, name)) return fallback;
  const value = body[name];
  if (typeof value !== 'number' || !Number.isInteger(value) || value < min || value > max) {
    errors.push({ field: name, message: `must be an integer from ${min} to ${max}` });
    return fallback;
  }
  return value;
}

/** Validates a parsed request body. Collects every error rather than stopping at the first. */
export function validateSubmission(body: unknown): { value: NewJob } | { errors: FieldError[] } {
  if (typeof body !== 'object' || body === null || Array.isArray(body)) {
    return { errors: [{ field: 'body', message: 'must be a JSON object' }] };
  }
  const record = body as Record<string, unknown>;
  const errors: FieldError[] = [];

  for (const key of Object.keys(record)) {
    if (!ALLOWED_FIELDS.has(key)) errors.push({ field: key, message: 'is not a recognised field' });
  }

  let input = '';
  if (!Object.hasOwn(record, 'input')) {
    errors.push({ field: 'input', message: 'is required' });
  } else if (typeof record.input !== 'string') {
    errors.push({ field: 'input', message: 'must be a string' });
  } else if (record.input.length < 1 || record.input.length > MAX_INPUT_LENGTH || record.input.trim() === '') {
    errors.push({ field: 'input', message: `must be 1 to ${MAX_INPUT_LENGTH} characters and not only whitespace` });
  } else {
    input = record.input;
  }

  const steps = integerField(record, 'steps', 1, MAX_STEPS, DEFAULT_STEPS, errors);
  const failAttempts = integerField(record, 'failAttempts', 0, MAX_FAIL_ATTEMPTS, DEFAULT_FAIL_ATTEMPTS, errors);

  if (errors.length > 0) return { errors };
  return { value: { input, steps, failAttempts } };
}

/** Returns a field error when an Idempotency-Key header is present and malformed. */
export function validateIdempotencyKey(value: string | undefined): FieldError | undefined {
  if (value === undefined) return undefined;
  return IDEMPOTENCY_KEY_PATTERN.test(value)
    ? undefined
    : { field: 'Idempotency-Key', message: 'must match ^[A-Za-z0-9_-]{1,128}$' };
}

