  if (typeof value !== 'number' || !Number.isInteger(value) || value < min || value > max) {
    errors.push({ field: name, message: `must be an integer from ${min} to ${max}` });
    return fallback;
  }
  return value;
}

/** Validates a parsed request body. Collects every error rather than stopping at the first. */
export function validateSubmission(body: unknown): { value: NewJob } | { errors: FieldError[] } {
  if (typeof body !== 'object' || body === null || Array.isArray(body)) {
    return { errors: [{ field: 'body', message: 'must be a JSON object' }] };
  }
  const record = body as Record<string, unknown>;
  const errors: FieldError[] = [];

  for (const key of Object.keys(record)) {
    if (!ALLOWED_FIELDS.has(key)) errors.push({ field: key, message: 'is not a recognised field' });
  }

  let input = '';
  if (!Object.hasOwn(record, 'input')) {
    errors.push({ field: 'input', message: 'is required' });
  } else if (typeof record.input !== 'string') {
    errors.push({ field: 'input', message: 'must be a string' });
  } else if (record.input.length < 1 || record.input.length > MAX_INPUT_LENGTH || record.input.trim() === '') {
    errors.push({ field: 'input', message: `must be 1 to ${MAX_INPUT_LENGTH} characters and not only whitespace` });
  } else {
    input = record.input;
  }

  const steps = integerField(record, 'steps', 1, MAX_STEPS, DEFAULT_STEPS, errors);
  const failAttempts = integerField(record, 'failAttempts', 0, MAX_FAIL_ATTEMPTS, DEFAULT_FAIL_ATTEMPTS, errors);

  if (errors.length > 0) return { errors };
  return { value: { input, steps, failAttempts } };
}

/** Returns a field error when an Idempotency-Key header is present and malformed. */
export function validateIdempotencyKey(value: string | undefined): FieldError | undefined {
  if (value === undefined) return undefined;
  return IDEMPOTENCY_KEY_PATTERN.test(value)
    ? undefined
    : { field: 'Idempotency-Key', message: 'must match ^[A-Za-z0-9_-]{1,128}$' };
}

