import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import { dirname } from 'node:path';
import { toApiJob, type ApiJob, type JobRow, type NewJob } from './jobs.ts';

/** A worker heartbeat older than this means the worker is down. */
export const HEARTBEAT_STALE_MS = 3000;

/**
 * Opens the SQLite database shared by the server and worker processes and makes sure the schema
 * exists. Either process may call this first.
 */
export function openDatabase(path: string = process.env.DATABASE_PATH ?? 'data/jobs.db'): DatabaseSync {
  if (path !== ':memory:') mkdirSync(dirname(path), { recursive: true });
  const db = new DatabaseSync(path);
  // busy_timeout first: switching to WAL takes a brief exclusive lock, and the server and worker
  // open the same database at once, so the loser must wait rather than fail.
  db.exec('PRAGMA busy_timeout = 5000; PRAGMA journal_mode = WAL;');
  initSchema(db);
  return db;
}

function initSchema(db: DatabaseSync): void {
  db.exec(`
    CREATE TABLE IF NOT EXISTS jobs (
      seq INTEGER PRIMARY KEY AUTOINCREMENT,
      id TEXT NOT NULL UNIQUE,
      status TEXT NOT NULL CHECK (status IN ('queued', 'running', 'completed', 'failed')),
      input TEXT NOT NULL,
      steps INTEGER NOT NULL,
      fail_attempts INTEGER NOT NULL,
      attempts INTEGER NOT NULL DEFAULT 0,
      completed INTEGER NOT NULL DEFAULT 0,
      output TEXT,
      error TEXT,
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL,
      idempotency_key TEXT UNIQUE,
      available_at INTEGER NOT NULL
    );
    CREATE INDEX IF NOT EXISTS jobs_claim ON jobs (status, available_at, seq);
    CREATE TABLE IF NOT EXISTS worker_state (
      id INTEGER PRIMARY KEY CHECK (id = 1),
      heartbeat_at INTEGER NOT NULL
    );
    INSERT OR IGNORE INTO worker_state (id, heartbeat_at) VALUES (1, 0);
  `);
}

export type CreateResult = { kind: 'created'; job: ApiJob } | { kind: 'replayed'; job: ApiJob } | { kind: 'conflict' };

/**
 * Creates a queued job, or resolves an Idempotency-Key replay. The whole decision runs in one
 * immediate write transaction, so concurrent submissions with the same key cannot both insert.
 */
export function createJob(db: DatabaseSync, payload: NewJob, key: string | undefined): CreateResult {
  db.exec('BEGIN IMMEDIATE');
  try {
    let result: CreateResult;
    const existing = key === undefined ? undefined : (selectByKey(db, key) as JobRow | undefined);
    if (existing) {
      const same =
        existing.input === payload.input && existing.steps === payload.steps && existing.fail_attempts === payload.failAttempts;
      result = same ? { kind: 'replayed', job: toApiJob(existing) } : { kind: 'conflict' };
    } else {
      const id = randomUUID();
      const now = new Date().toISOString();
      db.prepare(
        `INSERT INTO jobs (id, status, input, steps, fail_attempts, created_at, updated_at, idempotency_key, available_at)
         VALUES (?, 'queued', ?, ?, ?, ?, ?, ?, ?)`,
      ).run(id, payload.input, payload.steps, payload.failAttempts, now, now, key ?? null, Date.now());
      const row = selectById(db, id) as JobRow;
      result = { kind: 'created', job: toApiJob(row) };
    }
    db.exec('COMMIT');
    return result;
  } catch (error) {
    rollback(db);
    throw error;
  }
}

function selectByKey(db: DatabaseSync, key: string): unknown {
  return db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?').get(key);
}

export function selectById(db: DatabaseSync, id: string): JobRow | undefined {
  return db.prepare('SELECT * FROM jobs WHERE id = ?').get(id) as JobRow | undefined;
}

/** Lists jobs newest first, using the insertion sequence for a deterministic order. */
export function listJobs(db: DatabaseSync): ApiJob[] {
  return (db.prepare('SELECT * FROM jobs ORDER BY seq DESC').all() as unknown as JobRow[]).map(toApiJob);
}

export function getJob(db: DatabaseSync, id: string): ApiJob | undefined {
  const row = selectById(db, id);
  return row ? toApiJob(row) : undefined;
}

/** True when the worker has written a heartbeat within the last HEARTBEAT_STALE_MS. */
export function isWorkerUp(db: DatabaseSync, now: number = Date.now()): boolean {
  const row = db.prepare('SELECT heartbeat_at FROM worker_state WHERE id = 1').get() as { heartbeat_at: number } | undefined;
  return row !== undefined && row.heartbeat_at > 0 && now - row.heartbeat_at <= HEARTBEAT_STALE_MS;
}

export function rollback(db: DatabaseSync): void {
  try {
    db.exec('ROLLBACK');
  } catch {
    // no transaction was open
  }
}

