import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { createJob, getJob, isWorkerUp, listJobs, openDatabase, rollback } from './db.ts';
import { validateIdempotencyKey, validateSubmission, type FieldError, type NewJob } from './jobs.ts';

const MAX_BODY_BYTES = 64 * 1024;
const DRAIN_MS = 3000;
const HARD_EXIT_MS = 5000;

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

function sendJson(res: ServerResponse, status: number, body: unknown, headers: Record<string, string> = {}): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', ...headers });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[], headers?: Record<string, string>): void {
  const error: { code: string; message: string; fields?: FieldError[] } = { code, message };
  if (fields) error.fields = fields;
  sendJson(res, status, { error }, headers);
}

function sendInvalid(res: ServerResponse, fields: FieldError[]): void {
  sendError(res, 400, 'invalid_request', 'The request is invalid.', fields);
}

function methodNotAllowed(res: ServerResponse, allowed: string[]): void {
  sendError(res, 405, 'method_not_allowed', 'Method not allowed for this path.', undefined, { allow: allowed.join(', ') });
}

/** Reads the whole body as text, or returns null when it is too large or the stream fails. */
async function readText(req: IncomingMessage): Promise<string | null> {
  const chunks: Buffer[] = [];
  let size = 0;
  try {
    for await (const chunk of req) {
      const buffer = chunk as Buffer;
      size += buffer.length;
      if (size > MAX_BODY_BYTES) return null;
      chunks.push(buffer);
    }
  } catch {
    return null;
  }
  return Buffer.concat(chunks).toString('utf8');
}

function isJsonContentType(value: string | undefined): boolean {
  if (value === undefined) return false;
  const mediaType = value.split(';', 1)[0]!.trim().toLowerCase();
  return mediaType === 'application/json';
}

async function handleCreate(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const text = await readText(req);
  const errors: FieldError[] = [];

  const keyError = validateIdempotencyKey(req.headers['idempotency-key']);
  if (keyError) errors.push(keyError);

  let payload: NewJob | undefined;
  if (text === null || !isJsonContentType(req.headers['content-type'])) {
    errors.unshift({ field: 'body', message: 'must be a JSON body sent with Content-Type application/json' });
  } else {
    let parsed: unknown;
    try {
      parsed = JSON.parse(text);
    } catch {
      errors.unshift({ field: 'body', message: 'is not valid JSON' });
    }
    if (parsed !== undefined || errors.length === 0) {
      if (errors.length === 0) {
        const result = validateSubmission(parsed);
        if ('errors' in result) errors.push(...result.errors);
        else payload = result.value;
      }
    }
  }

  if (errors.length > 0 || payload === undefined) {
    sendInvalid(res, errors.length > 0 ? errors : [{ field: 'body', message: 'is invalid' }]);
    return;
  }

  const key = req.headers['idempotency-key'];
  const outcome = createJob(db, payload, key);
  if (outcome.kind === 'conflict') {
    sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
  } else if (outcome.kind === 'replayed') {
    sendJson(res, 200, outcome.job);
  } else {
    sendJson(res, 201, outcome.job);
  }
}

async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  const method = req.method ?? 'GET';

  if (pathname === '/') {
    if (method !== 'GET') return methodNotAllowed(res, ['GET']);
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }

  if (pathname === '/health') {
    if (method !== 'GET') return methodNotAllowed(res, ['GET']);
    return sendJson(res, 200, { status: 'ok', worker: isWorkerUp(db) ? 'up' : 'down' });
  }

  if (pathname === '/api/jobs') {
    if (method === 'GET') return sendJson(res, 200, { jobs: listJobs(db) });
    if (method === 'POST') return handleCreate(req, res);
    return methodNotAllowed(res, ['GET', 'POST']);
  }

  const idMatch = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (idMatch) {
    if (method !== 'GET') return methodNotAllowed(res, ['GET']);
    const job = getJob(db, idMatch[1]!);
    if (!job) return sendError(res, 404, 'not_found', 'No job has that id.');
    return sendJson(res, 200, job);
  }

  sendError(res, 404, 'not_found', 'No such route.');
}

const server = createServer((req, res) => {
  handle(req, res).catch((error: unknown) => {
    console.error('request failed:', error);
    rollback(db);
    if (!res.headersSent) sendError(res, 500, 'internal_error', 'An unexpected error occurred.');
    else res.end();
  });
});

const port = Number(process.env.PORT ?? 3000);
server.listen(port, () => console.log(`server listening on ${port}`));

let shuttingDown = false;
function shutdown(): void {
  if (shuttingDown) return;
  shuttingDown = true;
  console.log('server shutting down');
  const finish = () => {
    db.close();
    process.exit(0);
  };
  server.close(finish);
  server.closeIdleConnections();
  setTimeout(() => server.closeAllConnections(), DRAIN_MS);
  setTimeout(finish, HARD_EXIT_MS);
}

process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

