import { setTimeout as sleep } from 'node:timers/promises';
import type { DatabaseSync, StatementSync } from 'node:sqlite';
import { openDatabase, rollback, selectById } from './db.ts';
import { MAX_ATTEMPTS, RETRY_DELAY_MS, STEP_MS, TRANSIENT_ERROR, type JobRow } from './jobs.ts';

const POLL_MS = 100;
const HEARTBEAT_MS = 500;
const ERROR_BACKOFF_MS = 1000;
const INTERRUPTED_ERROR = 'worker stopped during the final attempt';

const db = openDatabase();
const controller = new AbortController();
let stopping = false;

function stop(): void {
  if (stopping) return;
  stopping = true;
  controller.abort();
}
process.on('SIGINT', stop);
process.on('SIGTERM', stop);

/** Waits for `ms`, returning early when shutdown begins. */
async function pause(ms: number): Promise<void> {
  try {
    await sleep(ms, undefined, { signal: controller.signal });
  } catch {
    // aborted by shutdown
  }
}

const statements = {
  heartbeat: db.prepare('UPDATE worker_state SET heartbeat_at = ? WHERE id = 1'),
  nextEligible: db.prepare("SELECT * FROM jobs WHERE status = 'queued' AND available_at <= ? ORDER BY seq ASC LIMIT 1"),
  claim: db.prepare(
    "UPDATE jobs SET status = 'running', attempts = attempts + 1, completed = 0, output = NULL, error = NULL, updated_at = ? WHERE id = ?",
  ),
  running: db.prepare("SELECT * FROM jobs WHERE status = 'running'"),
  progress: db.prepare("UPDATE jobs SET completed = ?, updated_at = ? WHERE id = ? AND status = 'running' AND attempts = ?"),
  complete: db.prepare(
    "UPDATE jobs SET status = 'completed', completed = steps, output = ?, error = NULL, updated_at = ? WHERE id = ? AND status = 'running' AND attempts = ?",
  ),
  requeue: db.prepare(
    "UPDATE jobs SET status = 'queued', completed = 0, output = NULL, error = NULL, available_at = ?, updated_at = ? WHERE id = ? AND status = 'running' AND attempts = ?",
  ),
  fail: db.prepare(
    "UPDATE jobs SET status = 'failed', completed = 0, output = NULL, error = ?, updated_at = ? WHERE id = ? AND status = 'running' AND attempts = ?",
  ),
} satisfies Record<string, StatementSync>;

function beat(value: number): void {
  try {
    statements.heartbeat.run(value);
  } catch (error) {
    console.error('heartbeat failed:', error);
  }
}

/**
 * Recovers jobs left `running` by an earlier worker. Each interrupted attempt stays counted.
 * Jobs with attempts left are requeued; a job that already used its final attempt is failed.
 */
function recoverInterrupted(): void {
  const now = Date.now();
  const stamp = new Date(now).toISOString();
  transaction(db, () => {
    for (const row of statements.running.all() as unknown as JobRow[]) {
      if (row.attempts < MAX_ATTEMPTS) {
        statements.requeue.run(now, stamp, row.id, row.attempts);
      } else {
        const error = row.fail_attempts >= row.attempts ? TRANSIENT_ERROR : INTERRUPTED_ERROR;
        statements.fail.run(error, stamp, row.id, row.attempts);
      }
    }
  });
}

/** Claims the oldest eligible job in a short write transaction. */
function claimNext(): JobRow | undefined {
  if (!statements.nextEligible.get(Date.now())) return undefined;
  return transaction(db, () => {
    const row = statements.nextEligible.get(Date.now()) as JobRow | undefined;
    if (!row) return undefined;
    statements.claim.run(new Date().toISOString(), row.id);
    return selectById(db, row.id);
  });
}

function transaction<T>(database: DatabaseSync, work: () => T): T {
  database.exec('BEGIN IMMEDIATE');
  try {
    const result = work();
    database.exec('COMMIT');
    return result;
  } catch (error) {
    rollback(database);
    throw error;
  }
}

/** Runs one claimed attempt. Every write is guarded by status and attempt number. */
async function runAttempt(job: JobRow): Promise<void> {
  const attempt = job.attempts;

  for (let step = 1; step <= job.steps; step++) {
    await pause(STEP_MS);
    if (stopping) return; // the job stays `running`; startup recovery handles it

    if (step === 1 && attempt <= job.fail_attempts) {
      failAttempt(job, attempt);
      return;
    }

    const stamp = new Date().toISOString();
    if (step < job.steps) {
      statements.progress.run(step, stamp, job.id, attempt);
    } else {
      statements.complete.run(job.input.toUpperCase(), stamp, job.id, attempt);
    }
  }
}

function failAttempt(job: JobRow, attempt: number): void {
  const stamp = new Date().toISOString();
  transaction(db, () => {
    if (attempt < MAX_ATTEMPTS) {
      statements.requeue.run(Date.now() + RETRY_DELAY_MS, stamp, job.id, attempt);
    } else {
      statements.fail.run(TRANSIENT_ERROR, stamp, job.id, attempt);
    }
  });
}

async function main(): Promise<void> {
  console.log('worker started');
  recoverInterrupted();
  beat(Date.now());
  const heartbeat = setInterval(() => beat(Date.now()), HEARTBEAT_MS);

  try {
    while (!stopping) {
      const job = claimNext();
      if (!job) {
        await pause(POLL_MS);
        continue;
      }
      try {
        await runAttempt(job);
      } catch (error) {
        console.error('attempt failed unexpectedly:', error);
        await pause(ERROR_BACKOFF_MS);
      }
    }
  } finally {
    clearInterval(heartbeat);
    beat(0);
    db.close();
    console.log('worker stopped');
  }
}

main().catch((error: unknown) => {
  console.error('worker crashed:', error);
  process.exit(1);
});

